/* 학습 해설
 * Libfdt 정렬 사용법·byte word와 blob base 구별
 * DTB 공개 API의 C linkage·version·오류·정렬·byte 접근·반복/생성 macro·typed wrapper·pointer 수명·API 선택·binding·overlay 계약을 읽습니다.
 * 공개 bytewise word helper는 unaligned word 접근을 지원하려는 구현입니다. 그러나 DTB 전체 base는 library probe에서8바이트 정렬을 요구합니다. word 읽기 방식이 형식 pointer의 전체 정렬·bounds·유효성을 없애주는 것은 아닙니다. 오류와 helper의 목적을 함께 읽습니다.
 * 8개 byte offset load/store fixture와 blob+1 alignment 오류 fixture를 비교합니다. 서로 다른 계약이므로 한 검산이 다른 조건을 대체하지 않는 이유를 설명합니다.
 */
#define FDT_ERR_ALIGNMENT	19
	/* FDT_ERR_ALIGNMENT: The device tree base address is not 8-byte
	 * aligned. */

#define FDT_ERR_MAX		19

/* constants */
#define FDT_MAX_PHANDLE 0xfffffffe
	/* Valid values for phandles range from 1 to 2^32-2. */

/**********************************************************************/
/* Low-level functions (you probably don't need these)                */
/**********************************************************************/

#ifndef SWIG /* This function is not useful in Python */
const void *fdt_offset_ptr(const void *fdt, int offset, unsigned int checklen);
#endif
static inline void *fdt_offset_ptr_w(void *fdt, int offset, int checklen)
{
	return (void *)(uintptr_t)fdt_offset_ptr(fdt, offset, checklen);
}

uint32_t fdt_next_tag(const void *fdt, int offset, int *nextoffset);

/*
 * External helpers to access words from a device tree blob. They're built
 * to work even with unaligned pointers on platforms (such as ARMv5) that don't
 * like unaligned loads and stores.
 */

