/* 학습 해설
 * DTB overlay target property·32비트 식별자 해석
 * DTB overlay의 식별자 재배치, local/external 참조 해결, 기존 identity 보존, 재귀 병합, symbol 경로 변환과 실패 상태의 원리를 읽습니다.
 * fragment의 target property가 없으면0입니다. 길이가4가 아니거나 값이0xffffffff면 uint32 -1을 반환하고 정상은 CPU phandle 값을 얻습니다. 명시적 target0도 이 helper에서는0으로 다음 path fallback에 연결됩니다. 모든 property의 부재와 malformed를 같은 sentinel로 처리하지 않습니다.
 * 없는 target, 정상10, 길이3, 금지0xffffffff, target0의 분기를 표로 적습니다. helper의 raw sentinel과 공개 오류 반환을 구별합니다.
 */
static uint32_t overlay_get_target_phandle(const void *fdto, int fragment)
{
	const fdt32_t *val;
	int len;

	val = fdt_getprop(fdto, fragment, "target", &len);
	if (!val)
		return 0;

	if ((len != sizeof(*val)) || (fdt32_to_cpu(*val) == (uint32_t)-1))
		return (uint32_t)-1;

	return fdt32_to_cpu(*val);
}

int fdt_overlay_target_offset(const void *fdt, const void *fdto,
			      int fragment_offset, char const **pathp)
{
	uint32_t phandle;
	const char *path = NULL;
	int path_len = 0, ret;

	/* Try first to do a phandle based lookup */
	phandle = overlay_get_target_phandle(fdto, fragment_offset);
	if (phandle == (uint32_t)-1)
		return -FDT_ERR_BADPHANDLE;

