/* 학습 해설
 * DTB overlay target 선택·phandle 우선, 경로 fallback
 * DTB overlay의 식별자 재배치, local/external 참조 해결, 기존 identity 보존, 재귀 병합, symbol 경로 변환과 실패 상태의 원리를 읽습니다.
 * target phandle을 먼저 읽고 malformed sentinel이면 BADPHANDLE입니다. phandle0이면 target-path로 base를 찾고 nonzero면 base의 phandle 검색을 사용합니다. 정상 pathp는 경로 방식이면 overlay 내부 path, phandle 방식이면NULL을 받습니다. 반환 offset은 base 기준입니다.
 * 같은 soc를 target10 또는 target-path /soc로 가리킨 실제 fixture를 비교합니다. overlay fragment 위치와 base target 위치를 다른 공간으로 그립니다.
 */
int fdt_overlay_target_offset(const void *fdt, const void *fdto,
			      int fragment_offset, char const **pathp)
{
	uint32_t phandle;
	const char *path = NULL;
	int path_len = 0, ret;

	/* Try first to do a phandle based lookup */
	phandle = overlay_get_target_phandle(fdto, fragment_offset);
	if (phandle == (uint32_t)-1)
		return -FDT_ERR_BADPHANDLE;

	/* no phandle, try path */
	if (!phandle) {
		/* And then a path based lookup */
		path = fdt_getprop(fdto, fragment_offset, "target-path", &path_len);
		if (path)
			ret = fdt_path_offset(fdt, path);
		else
			ret = path_len;
	} else
		ret = fdt_node_offset_by_phandle(fdt, phandle);

	/*
	* If we haven't found either a target or a
	* target-path property in a node that contains a
	* __overlay__ subnode (we wouldn't be called
	* otherwise), consider it a improperly written
	* overlay
	*/

