/* 학습 해설
 * DTB overlay phandle 이동·delta와 wrap 거부
 * DTB overlay의 식별자 재배치, local/external 참조 해결, 기존 identity 보존, 재귀 병합, symbol 경로 변환과 실패 상태의 원리를 읽습니다.
 * phandle property 길이를4로 확인하고 val+delta가val보다 작아지거나 결과가0xffffffff이면 NOPHANDLES입니다. 정상은 bytewise fdt32 load/store로 같은 크기를 교체합니다. base max를delta로 사용해 overlay의 유효 local phandle을 base 영역 밖으로 옮기는 재배치 원리입니다.
 * base max10과 overlay3이13이 되는 계산, 최대0xfffffffe에1을 더해 거부되는 실제 fixture를 풉니다. 정수 overflow와 금지값 충돌을 구별합니다.
 */
static int overlay_phandle_add_offset(void *fdt, int node,
				      const char *name, uint32_t delta)
{
	fdt32_t *valp, val;
	int len;

	valp = fdt_getprop_w(fdt, node, name, &len);
	if (!valp)
		return len;

	if (len != sizeof(val))
		return -FDT_ERR_BADPHANDLE;

	val = fdt32_ld(valp);
	if (val + delta < val || val + delta == (uint32_t)-1)
		return -FDT_ERR_NOPHANDLES;

	fdt32_st(valp, val + delta);
	return 0;
}

