/* 학습 해설
 * DTB local fixup 자료·tree와 평행한 metadata
 * DTB overlay의 식별자 재배치, local/external 참조 해결, 기존 identity 보존, 재귀 병합, symbol 경로 변환과 실패 상태의 원리를 읽습니다.
 * local fixup node의 property 이름은 실제 tree node의 같은 property를 가리키고 값은32비트 byte offset 배열입니다. fixup 길이가4의 배수가 아니면 BADOVERLAY, 실제 property가 없으면 부재를 BADOVERLAY로 바꿉니다. fixup subtree는 실제 overlay subtree와 이름으로 대응합니다.
 * new의 local/parentref/devref/unaligned property와 대응 fixup node를 그립니다. offset 배열의 값은 phandle 값 자체가 아니라 수정할 byte 위치라는 점을 적습니다.
 */
static int overlay_update_local_node_references(void *fdto,
						int tree_node,
						int fixup_node,
						uint32_t delta)
{
	int fixup_prop;
	int fixup_child;
	int ret;

	fdt_for_each_property_offset(fixup_prop, fdto, fixup_node) {
		const fdt32_t *fixup_val;
		const char *name;
		char *tree_val;
		int fixup_len;
		int tree_len;
		int i;

		fixup_val = fdt_getprop_by_offset(fdto, fixup_prop,
						  &name, &fixup_len);
		if (!fixup_val)
			return fixup_len;

		if (fixup_len % sizeof(uint32_t))
			return -FDT_ERR_BADOVERLAY;
		fixup_len /= sizeof(uint32_t);

