/* 학습 해설
 * DTB local fixup 전체 wrapper·선택 metadata
 * DTB overlay의 식별자 재배치, local/external 참조 해결, 기존 identity 보존, 재귀 병합, symbol 경로 변환과 실패 상태의 원리를 읽습니다.
 * /__local_fixups__를 찾고 NOTFOUND이면 조정할 local 참조가 없어0입니다. 다른 탐색 오류는 반환합니다. 정상 metadata가 있으면 실제 overlay root0과 fixup root를 짝지어 재귀 수정합니다. 선택 metadata 부재를 tree 전체 유효성 검증 결과라고 해석하지 않습니다.
 * fixup 없는 단순 overlay와 참조 있는 overlay를 비교합니다. 정의 phandle 이동 뒤 이 wrapper가 참조를 이동하는 pipeline 순서를 적습니다.
 */
static int overlay_update_local_references(void *fdto, uint32_t delta)
{
	int fixups;

	fixups = fdt_path_offset(fdto, "/__local_fixups__");
	if (fixups < 0) {
		/* There's no local phandles to adjust, bail out */
		if (fixups == -FDT_ERR_NOTFOUND)
			return 0;

		return fixups;
	}

	/*
	 * Update our local references from the root of the tree
	 */
	return overlay_update_local_node_references(fdto, 0, fixups,
						    delta);
}

