/* 학습 해설
 * DTB external fixup 한 위치·substring 경로와 부분 덮기
 * DTB overlay의 식별자 재배치, local/external 참조 해결, 기존 identity 보존, 재귀 병합, symbol 경로 변환과 실패 상태의 원리를 읽습니다.
 * overlay의 지정 길이 path로 node를 찾고 부재면 BADOVERLAY입니다. base phandle을 big-endian4byte로 만들어 지정 길이 property 이름과 poffset 위치의 inplace partial 함수에 전달합니다. 이 단계는 크기를 늘리거나 새 property를 생성하는 merge가 아닙니다.
 * remote placeholder0xffffffff의 byte0에 base device5를 쓰는 실제 fixture를 읽습니다. 참조 정의를 찾는 단계와 byte 위치를 덮는 단계를 구별합니다.
 */
static int overlay_fixup_one_phandle(void *fdt, void *fdto,
				     int symbols_off,
				     const char *path, uint32_t path_len,
				     const char *name, uint32_t name_len,
				     int poffset, uint32_t phandle)
{
	fdt32_t phandle_prop;
	int fixup_off;

	if (symbols_off < 0)
		return symbols_off;

	fixup_off = fdt_path_offset_namelen(fdto, path, path_len);
	if (fixup_off == -FDT_ERR_NOTFOUND)
		return -FDT_ERR_BADOVERLAY;
	if (fixup_off < 0)
		return fixup_off;

	phandle_prop = cpu_to_fdt32(phandle);
	return fdt_setprop_inplace_namelen_partial(fdto, fixup_off,
						   name, name_len, poffset,
						   &phandle_prop,
						   sizeof(phandle_prop));
};

