/* 학습 해설
 * DTB external fixup 전체·없으면 선택 단계 생략
 * DTB overlay의 식별자 재배치, local/external 참조 해결, 기존 identity 보존, 재귀 병합, symbol 경로 변환과 실패 상태의 원리를 읽습니다.
 * /__fixups__가 NOTFOUND이면0으로 끝납니다. 있으면 base __symbols__ 위치를 얻고 fixup property마다 label 해결을 반복합니다. base symbols 부재는 즉시 항상 성공으로 무시하는 정책이 아니며 실제 참조 해결에서 필요한 자료 오류를 확인합니다. loop의 모든 malformed iterator 종료까지 실행한 증거는 아닙니다.
 * 외부 참조 없는 overlay와 devlabel 참조 있는 실제 tree를 비교합니다. local fixup과 external fixup의 서로 다른 metadata를 두 열로 적습니다.
 */
static int overlay_fixup_phandles(void *fdt, void *fdto)
{
	int fixups_off, symbols_off;
	int property;

	/* We can have overlays without any fixups */
	fixups_off = fdt_path_offset(fdto, "/__fixups__");
	if (fixups_off == -FDT_ERR_NOTFOUND)
		return 0; /* nothing to do */
	if (fixups_off < 0)
		return fixups_off;

	/* And base DTs without symbols */
	symbols_off = fdt_path_offset(fdt, "/__symbols__");
	if ((symbols_off < 0 && (symbols_off != -FDT_ERR_NOTFOUND)))
		return symbols_off;

	fdt_for_each_property_offset(property, fdto, fixups_off) {
		int ret;

		ret = overlay_fixup_phandle(fdt, fdto, symbols_off, property);
		if (ret)
			return ret;
	}

	return 0;

