/* 학습 해설
 * DTB 기존 node 충돌·overlay phandle를 base로 맞춤
 * DTB overlay의 식별자 재배치, local/external 참조 해결, 기존 identity 보존, 재귀 병합, symbol 경로 변환과 실패 상태의 원리를 읽습니다.
 * 겹치는 node의 phandle와 linux,phandle이 각각 존재하고 길이4이면 base phandle로 inplace 교체합니다. 전체 tree에 동일 번호를 새로 할당하는 함수가 아니라 merge할 같은 node의 기존 identity를 보존하는 단계입니다. 부재나 길이 불일치 property는 이 helper에서 별도로 바꾸지 않습니다.
 * overlay node11과 기존 soc10이 같은 target이면 최종10이 유지되는 실제 fixture를 풉니다. 최초delta 이동과 기존 identity 보존의 두 이유를 설명합니다.
 */
static int overlay_adjust_local_conflicting_phandle(void *fdto, int node,
						    uint32_t fdt_phandle)
{
	const fdt32_t *php;
	int len, ret;

	php = fdt_getprop(fdto, node, "phandle", &len);
	if (php && len == sizeof(*php)) {
		ret = fdt_setprop_inplace_u32(fdto, node, "phandle", fdt_phandle);
		if (ret)
			return ret;
	}

	php = fdt_getprop(fdto, node, "linux,phandle", &len);
	if (php && len == sizeof(*php)) {
		ret = fdt_setprop_inplace_u32(fdto, node, "linux,phandle", fdt_phandle);
		if (ret)
			return ret;
	}

	return 0;
}

