/* 학습 해설
 * DTB overwrite 보호 전체·fragment 선택과 target 오류
 * DTB overlay의 식별자 재배치, local/external 참조 해결, 기존 identity 보존, 재귀 병합, symbol 경로 변환과 실패 상태의 원리를 읽습니다.
 * overlay root의 fragment를 순회하고 __overlay__ child가 없으면 넘어갑니다. target NOTFOUND는 보호할 기존 subtree가 없다고 이 단계에서 넘어가지만 다른 오류는 반환합니다. 이후 merge 단계도 target을 다시 찾으므로 이 skip이 전체 적용 성공을 보장하는 것은 아닙니다.
 * 보호 단계와 실제 merge의 target 처리 조건을 비교합니다. __symbols__/__fixups__ 같은 root child를 merge fragment로 오해하지 않는 조건을 적습니다.
 */
static int overlay_prevent_phandle_overwrite(void *fdt, void *fdto)
{
	int fragment;

	fdt_for_each_subnode(fragment, fdto, 0) {
		int overlay;
		int target;
		int ret;

		overlay = fdt_subnode_offset(fdto, fragment, "__overlay__");
		if (overlay == -FDT_ERR_NOTFOUND)
			continue;

		if (overlay < 0)
			return overlay;

		target = fdt_overlay_target_offset(fdt, fdto, fragment, NULL);
		if (target == -FDT_ERR_NOTFOUND)
			/*
			 * The subtree doesn't exist in the base, so nothing
			 * will be overwritten.
			 */
			continue;
		else if (target < 0)
			return target;

