/* 학습 해설
 * DTB symbol 경로 길이·parent를 반복 조회
 * DTB overlay의 식별자 재배치, local/external 참조 해결, 기존 identity 보존, 재귀 병합, symbol 경로 변환과 실패 상태의 원리를 읽습니다.
 * target 이름을 얻고 parent를 반복해서 올라가며 각 이름 길이+slash를 더합니다. root 빈 이름에서 끝나고 합0이면 root 경로/의 길이1을 반환합니다. 결과는 NUL 제외 문자 수입니다. parent 조회 자체가 flat tree scan이므로 단순 parent pointer traversal보다 비용이 커질 수 있습니다.
 * /soc 길이4와 root 길이1을 계산합니다. symbol buffer에NUL과 relative path를 붙이는 다음 단계의 용량 수식을 연결합니다.
 */
static int get_path_len(const void *fdt, int nodeoffset)
{
	int len = 0, namelen;
	const char *name;

	FDT_RO_PROBE(fdt);

	for (;;) {
		name = fdt_get_name(fdt, nodeoffset, &namelen);
		if (!name)
			return namelen;

		/* root? we're done */
		if (namelen == 0)
			break;

		nodeoffset = fdt_parent_offset(fdt, nodeoffset);
		if (nodeoffset < 0)
			return nodeoffset;
		len += namelen + 1;
	}

	/* in case of root pretend it's "/" */
	if (len == 0)
		len++;
	return len;

