/* 학습 해설
 * DTB overlay 적용 pipeline·정의·참조·병합 순서
 * DTB overlay의 식별자 재배치, local/external 참조 해결, 기존 identity 보존, 재귀 병합, symbol 경로 변환과 실패 상태의 원리를 읽습니다.
 * 두 최소 probe 뒤 base max를delta로 얻습니다. local phandle 정의 이동→local 참조 이동→external label fixup→기존 phandle overwrite 보호→payload merge→symbol 갱신 순서입니다. 참조를 고치기 전에 병합하면 두 tree의 번호 공간과 기존 identity가 섞일 수 있어 단계 순서가 의미를 갖습니다.
 * base10/5, overlay1/2/3/4의 실제 변환과 final10/5/13/14를 화살표로 적습니다. 각 단계가 수정하는 tree와 metadata를 두 열로 설명합니다.
 */
int fdt_overlay_apply(void *fdt, void *fdto)
{
	uint32_t delta;
	int ret;

	FDT_RO_PROBE(fdt);
	FDT_RO_PROBE(fdto);

	ret = fdt_find_max_phandle(fdt, &delta);
	if (ret)
		goto err;

	/* Increase all phandles in the fdto by delta */
	ret = overlay_adjust_local_phandles(fdto, delta);
	if (ret)
		goto err;

	/* Adapt the phandle values in fdto to the above increase */
	ret = overlay_update_local_references(fdto, delta);
	if (ret)
		goto err;

	/* Update fdto's phandles using symbols from fdt */
	ret = overlay_fixup_phandles(fdt, fdto);
	if (ret)
		goto err;

